template <typename T> struct AddOne { constexpr static T calc(T v) { return v + 1; } };
template <typename T> struct Double { constexpr static T calc(T v) { return v * 2; } };

template <typename T, bool Fast>
using Strategy = typename std::conditional<
    Fast,
    AddOne<T>,
    Double<T>
>::type;

template <typename T, bool Fast>
constexpr T Process(T value) {
    // Strategy type selected entirely at compile time
    return Strategy<T, Fast>::calc(value);
}

constexpr int result_A = Process<int, true>(100);  // Policy: AddOne
constexpr int result_B = Process<int, false>(100); // Policy: Double
